RULES = []
for idx, (cwe, title, category, severity, pattern, fix) in enumerate(_RULE_DATA, 1):
    RULES.append({"id": f"CWE-R{idx:03d}", "cwe": cwe, "title": title,
                  "category": category, "severity": severity, "pattern": pattern,
                  "message": f"Potential {title} indicator detected.", "fix": fix})
_COMPILED = [(r, re.compile(r["pattern"], re.I)) for r in RULES]

def get_security_rule_catalog():
    return [{k: v for k, v in rule.items() if k != "pattern"} for rule in RULES]


def run_multilanguage_security_analysis(source_code, language="unknown"):
    """Run local heuristic source signatures; source is never executed."""
    if not isinstance(source_code, str) or not source_code.strip():
        return []
    findings, seen = [], set()
    for number, line in enumerate(source_code.splitlines(), 1):
        for rule, compiled in _COMPILED:
            if compiled.search(line):
                key = (rule["id"], number)
                if key in seen:
                    continue
                seen.add(key)
                findings.append({
                    "id": rule["id"], "rule_id": rule["id"], "pattern_id": rule["id"],
                    "cwe": rule["cwe"], "cwe_id": rule["cwe"],
                    "category": rule["category"], "severity": rule["severity"],
                    "line": number, "lineno": number, "function": "source/module",
                    "title": rule["title"], "message": rule["message"],
                    "fix": rule["fix"], "remediation": rule["fix"],
                    "evidence": line.strip()[:300], "language": language,
                })
    return findings


def get_rule_count():
    return len(RULES)
